package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class GreeterTest {

    @Test
    fun greetsWithCurrentName() {
        val got = Greeter.greet()
        val want = "Hello, " + Config.NAME + "!"
        assertEquals(want, got, "Greeter.greet() must use the CURRENT Config.NAME, not a stale value")
    }
}

